#!/usr/bin/env node
// Regenerates src/loc/modules/index.ts from the module JSON files present, in number order.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
const dir = new URL('../src/loc/modules/', import.meta.url).pathname;
const files = readdirSync(dir).filter(f => f.endsWith('.json')).map(f => ({ f, n: JSON.parse(readFileSync(dir + f, 'utf8')).number })).sort((a, b) => a.n - b.n);
const name = (f) => 'm' + f.replace(/^m(\d+)-.*/, '$1');
writeFileSync(dir + 'index.ts', `/**
 * Localization module registry (generated by scripts/gen-loc-index.mjs; rerun after adding a module).
 */
import type { EegModule } from '../../eeg/types';

${files.map(({ f }) => `import ${name(f)} from './${f}';`).join('\n')}

export const LOC_MODULES: EegModule[] = [
  ${files.map(({ f }) => name(f)).join(', ')},
] as EegModule[];

export function getLocModule(id: string): EegModule | undefined {
  return LOC_MODULES.find(m => m.id === id);
}
`);
console.log(`index: ${files.length} modules`);
